def x_measure_consensus_latency__mutmut_orig(
    agent_counts: List[int], trials: int = 100
) -> Dict[str, float]:
    """
    Measure consensus decision latency.

    Args:
        agent_counts: List of agent counts to test
        trials: Number of trials per configuration

    Returns:
        Dictionary with latency statistics
    """
    logger.info(f"Measuring consensus latency for {agent_counts}")

    results = {}

    for num_agents in agent_counts:
        coordinator = MultiAgentCoordinator()

        for i in range(num_agents):
            coordinator.register_agent(f"agent_{i}", role="analyzer", weight=1.0)

        latencies = []

        for trial in range(trials):
            decisions = [
                AgentDecision(
                    f"agent_{i}",
                    "approve" if np.random.random() > 0.4 else "reject",
                    np.random.uniform(0.7, 0.95),
                    datetime.now(),
                )
                for i in range(num_agents)
            ]

            start_time = datetime.now()
            coordinator.reach_consensus(decisions, strategy=VotingStrategy.MAJORITY)
            latency_ms = (datetime.now() - start_time).total_seconds() * 1000

            latencies.append(latency_ms)

        avg_latency = np.mean(latencies)
        max_latency = np.max(latencies)
        p95_latency = np.percentile(latencies, 95)

        results[f"agents_{num_agents}"] = {
            "mean_ms": avg_latency,
            "max_ms": max_latency,
            "p95_ms": p95_latency,
            "target_met": avg_latency < TARGET_CONSENSUS_LATENCY_MS,
        }

        logger.info(
            f"N={num_agents}: latency = {avg_latency:.2f}ms (max: {max_latency:.2f}ms, p95: {p95_latency:.2f}ms)"
        )

    return results


